import re

_TITLE_RE: re.Pattern[str] = re.compile(
    r"<title(?=[\s>])[^>]*>(.*?)</title\s*>",
    re.IGNORECASE | re.DOTALL,
)


def title_of(html: str) -> str:
    """Return the text between the first <title> and its closing </title>.

    Rules:
    - Tag names match case-insensitively (<TITLE>...</Title> works).
    - The opening tag may carry attributes (<title id="x">).
    - The tag name must be exactly "title"; <titles> or <titlefoo> don't match.
    - The text is returned exactly as written: no whitespace stripping and
      no HTML entity decoding. It may span multiple lines.
    - If there are several title elements, the first one is used.
    - Return "" if there is no title, if the title is empty, or if the
      opening tag has no closing </title> after it.
    - Pure string processing; never touches the network.
    """
    m = _TITLE_RE.search(html)
    if m is None:
        return ""
    return m.group(1)


def test_basic() -> None:
    html = "<html><head><title>Hello</title></head><body></body></html>"
    assert title_of(html) == "Hello"


def test_empty_input() -> None:
    assert title_of("") == ""


def test_no_title() -> None:
    assert title_of("<html><head></head><body>hi</body></html>") == ""


def test_empty_title() -> None:
    assert title_of("<title></title>") == ""


def test_case_insensitive() -> None:
    assert title_of("<TITLE>Upper</TITLE>") == "Upper"
    assert title_of("<TiTlE>Mixed</tItLe>") == "Mixed"


def test_attributes_on_opening_tag() -> None:
    assert title_of('<title id="t" lang="en">With attrs</title>') == "With attrs"
    assert title_of("<title >Space</title>") == "Space"


def test_unclosed_title() -> None:
    assert title_of("<title>never closed") == ""


def test_first_title_wins() -> None:
    assert title_of("<title>one</title><title>two</title>") == "one"


def test_whitespace_preserved() -> None:
    assert title_of("<title>  padded \n</title>") == "  padded \n"


def test_multiline_title() -> None:
    assert title_of("<title>line1\nline2</title>") == "line1\nline2"


def test_entities_not_decoded() -> None:
    assert title_of("<title>Tom &amp; Jerry</title>") == "Tom &amp; Jerry"


def test_similar_tag_names_do_not_match() -> None:
    assert title_of("<titles>nope</titles>") == ""
    assert title_of("<titlefoo>nope</titlefoo>") == ""


def test_similar_tag_before_real_title() -> None:
    assert title_of("<titles>nope</titles><title>yes</title>") == "yes"


def test_title_in_svg_like_context_still_first_match() -> None:
    html = "<svg><title>icon</title></svg><title>page</title>"
    assert title_of(html) == "icon"
